) ENGINE = InnoDB AUTO_INCREMENT = 18424 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'ข้อมูลเงินและเป้าหมายจัดสรรเริ่มต้น' ROW_FORMAT = Dynamic;

