-- ----------------------------
-- Procedure structure for sp_finalize_nhso_data
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_finalize_nhso_data`;
delimiter ;;
CREATE PROCEDURE `sp_finalize_nhso_data`(IN p_batch_id VARCHAR(100), IN p_user_id INT)
BEGIN
    DECLARE v_fiscal_year INT;

    DECLARE exit handler for sqlexception
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    -- 1. หาปีงบประมาณของข้อมูลชุดนี้ที่กำลังจะนำเข้า
    SELECT fiscal_year INTO v_fiscal_year 
    FROM tmp_nhso_data 
    WHERE batch_id = p_batch_id 
    LIMIT 1;

    -- 2. เคลียร์สถานะข้อมูลเก่าของปีงบประมาณเดียวกัน ให้ is_valid = 0 (Soft Delete)
    -- เพื่อให้ Dashboard ไม่เอาข้อมูลเก่าไปรวมคำนวณ
    IF v_fiscal_year IS NOT NULL THEN
        UPDATE trn_budget_allocation 
        SET is_valid = 0 
        WHERE fiscal_year = v_fiscal_year;
    END IF;

    -- 3. นำเข้าข้อมูลชุดใหม่ที่จับคู่ (Map) สำเร็จ โดยให้ is_valid = 1 (เป็นข้อมูลล่าสุด)
        batch_id, fiscal_year, month_count, hoscode, 
        sub_activity_id, visit_count, allocated_budget, is_valid, updated_by
    )
    SELECT 
        t.batch_id, 
        t.fiscal_year, 
        MAX(t.month_count) AS month_count, 
        t.hoscode, 
        m.sub_activity_id, 
        SUM(t.visit_count) AS visit_count,
        SUM(t.allocated_budget) AS allocated_budget,
        1 AS is_valid,
        p_user_id
    FROM tmp_nhso_data t
    JOIN map_nhso_activities m 
      ON t.sub_activity_name = m.mapping_desc 
      AND t.fiscal_year = m.fiscal_year
    WHERE t.batch_id = p_batch_id
    GROUP BY 
        t.batch_id, 
        t.fiscal_year, 
        t.hoscode, 
        m.sub_activity_id;

    -- 4. Select ดึงรายชื่อกิจกรรมที่ Map ไม่ผ่านเพื่อส่งกลับไปให้ Frontend
    SELECT t.sub_activity_name, COUNT(*) as error_count
    FROM tmp_nhso_data t
    LEFT JOIN map_nhso_activities m 
      ON t.sub_activity_name = m.mapping_desc 
      AND t.fiscal_year = m.fiscal_year
    WHERE t.batch_id = p_batch_id 
      AND m.sub_activity_id IS NULL
    GROUP BY t.sub_activity_name;

    -- 5. ล้างข้อมูล Temp ที่ประมวลผลเสร็จแล้ว
    DELETE FROM tmp_nhso_data WHERE batch_id = p_batch_id;

    COMMIT;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
